# This formula is regenerated by the ankra-cli release workflow from
# packaging/homebrew/ankra.rb.tmpl in ankraio/ankra-cli. Manual edits here
# will be overwritten on the next release; change the template instead.
#
# There is deliberately no `version` stanza: `brew audit` fails a tap whose
# declared version it can already scan from the stable URL (redundant_version),
# and every release URL below carries the tag. That is why the URLs interpolate
# nothing - the release workflow substitutes the version into them directly.
class Ankra < Formula
  desc "Command-line interface for the Ankra Kubernetes platform"
  homepage "https://ankra.io"
  license "Apache-2.0"

  livecheck do
    url :stable
    strategy :github_latest
  end

  on_macos do
    on_arm do
      url "https://github.com/ankraio/ankra-cli/releases/download/v0.71.0/ankra-cli-darwin-arm64"
      sha256 "8549d82f0f096a8bb7176d7e6921bc89c51f2d0198991a2ea851dbd17791acbb"
    end
    on_intel do
      url "https://github.com/ankraio/ankra-cli/releases/download/v0.71.0/ankra-cli-darwin-amd64"
      sha256 "85bab3c52dc7c7c0b72d62d908d9574c25dadbd26b98d621c31b01db0ae15b54"
    end
  end

  on_linux do
    on_arm do
      url "https://github.com/ankraio/ankra-cli/releases/download/v0.71.0/ankra-cli-linux-arm64"
      sha256 "09e85fcf49021aa47636f51b9105eae10708f7eb5eb9e8888594a835dfd37f9f"
    end
    on_intel do
